from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    R = len(grid)
    C = len(grid[0])

    # 1. Find all connected components of non-zero pixels
    visited = [[False] * C for _ in range(R)]
    components = []

    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = []
                q = deque([(r, c)])
                visited[r][c] = True
                while q:
                    curr_r, curr_c = q.popleft()
                    comp.append((curr_r, curr_c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc] and grid[nr][nc] != 0:
                            visited[nr][nc] = True
                            q.append((nr, nc))
                components.append(comp)

    if not components:
        return grid

    # 2. Identify the main region (largest component by pixel count)
    main_comp = max(components, key=len)
    main_set = set(main_comp)

    min_r = min(r for r, c in main_comp)
    max_r = max(r for r, c in main_comp)
    min_c = min(c for r, c in main_comp)
    max_c = max(c for r, c in main_comp)

    # Extract subgrid corresponding to the main region's bounding box
    subgrid = [row[min_c:max_c+1] for row in grid[min_r:max_r+1]]

    # Collect unique colors in the main region
    main_colors = set(grid[r][c] for r, c in main_comp)

    # 3. Find external pairs to determine color mapping
    mapping = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and (r, c) not in main_set:
                for dr, dc in [(0, 1), (1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        if grid[nr][nc] != 0 and (nr, nc) not in main_set:
                            v1 = grid[r][c]
                            v2 = grid[nr][nc]
                            if v1 != v2:
                                if v1 in main_colors and v2 not in main_colors:
                                    mapping[v1] = v2
                                elif v2 in main_colors and v1 not in main_colors:
                                    mapping[v2] = v1

    # 4. Build output grid by applying the mapping
    output = []
    for row in subgrid:
        new_row = []
        for val in row:
            new_row.append(mapping.get(val, val))
        output.append(new_row)

    return output

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.array(grid)
    H, W = arr.shape

    # Determine background color from corners
    corners = [arr[0, 0], arr[0, W-1], arr[H-1, 0], arr[H-1, W-1]]
    bg = max(set(corners), key=corners.count)

    mask = (arr != bg)

    # Find connected components of non-background cells (compartments) using BFS
    visited = np.zeros((H, W), dtype=bool)
    components = []

    for r in range(H):
        for c in range(W):
            if mask[r, c] and not visited[r, c]:
                comp_pixels = []
                queue = [(r, c)]
                visited[r, c] = True

                head = 0
                while head < len(queue):
                    curr_r, curr_c = queue[head]
                    head += 1
                    comp_pixels.append((curr_r, curr_c))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if mask[nr, nc] and not visited[nr, nc]:
                                visited[nr, nc] = True
                                queue.append((nr, nc))

                components.append(comp_pixels)

    if not components:
        return grid

    subgrids = []
    for comp in components:
        rs = [p[0] for p in comp]
        cs = [p[1] for p in comp]
        r_min, r_max = min(rs), max(rs)
        c_min, c_max = min(cs), max(cs)
        sub = arr[r_min:r_max+1, c_min:c_max+1]
        subgrids.append(sub)

    max_h = max(sub.shape[0] for sub in subgrids)
    max_w = max(sub.shape[1] for sub in subgrids)

    canvas = np.zeros((max_h, max_w), dtype=int)

    for sub in subgrids:
        sh, sw = sub.shape
        for r in range(sh):
            for c in range(sw):
                val = sub[r, c]
                if val != bg and val != 0:
                    canvas[r, c] = val

    return canvas.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Find all unique non-zero colors
    colors = set()
    for row in grid:
        for val in row:
            if val != 0:
                colors.add(val)

    color_info = []
    for c in colors:
        min_r, max_r = float('inf'), float('-inf')
        min_c, max_c = float('inf'), float('-inf')
        for r_idx, row in enumerate(grid):
            for c_idx, val in enumerate(row):
                if val == c:
                    if r_idx < min_r: min_r = r_idx
                    if r_idx > max_r: max_r = r_idx
                    if c_idx < min_c: min_c = c_idx
                    if c_idx > max_c: max_c = c_idx

        height = max_r - min_r + 1
        width = max_c - min_c + 1
        span = max(height, width)
        color_info.append({
            'color': c,
            'span': span,
            'min_r': min_r,
            'min_c': min_c
        })

    # Sort colors by span descending, then by position to ensure determinism
    color_info.sort(key=lambda x: (-x['span'], x['min_r'], x['min_c']))

    if not color_info:
        return []

    N = color_info[0]['span']
    output = [[0] * N for _ in range(N)]

    num_layers = len(color_info)
    for i, info in enumerate(color_info):
        c = info['color']
        r1, c1 = i, i
        r2, c2 = N - 1 - i, N - 1 - i

        if i == num_layers - 1:
            # Innermost layer: fill the remaining rectangle
            for r in range(r1, r2 + 1):
                for col_idx in range(c1, c2 + 1):
                    output[r][col_idx] = c
        else:
            # Outer/middle layers: draw border
            for r in range(r1, r2 + 1):
                for col_idx in range(c1, c2 + 1):
                    if r == r1 or r == r2 or col_idx == c1 or col_idx == c2:
                        output[r][col_idx] = c

    return output

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # 1. Locate the 7x7 box of 1s
    box_r, box_c = 0, 0
    max_ones = -1
    for r in range(H - 6):
        for c in range(W - 6):
            ones_count = 0
            for dr in range(7):
                for dc in range(7):
                    if grid[r + dr][c + dc] == 1:
                        ones_count += 1
            if ones_count > max_ones:
                max_ones = ones_count
                box_r, box_c = r, c

    # 2. Get indicator colors from the 4 inner positions of the 7x7 box
    c_tl = grid[box_r + 1][box_c + 1]
    c_tr = grid[box_r + 1][box_c + 5]
    c_bl = grid[box_r + 5][box_c + 1]
    c_br = grid[box_r + 5][box_c + 5]

    # 3. Extract the 3x3 shape for a given color from outside the 7x7 box
    def extract_shape(color: int) -> list[list[int]]:
        coords = []
        for r in range(H):
            for c in range(W):
                # Exclude pixels inside the 7x7 reference box
                if box_r <= r < box_r + 7 and box_c <= c < box_c + 7:
                    continue
                if grid[r][c] == color:
                    coords.append((r, c))

        if not coords:
            return [[0]*3 for _ in range(3)]

        min_r = min(r for r, c in coords)
        min_c = min(c for r, c in coords)

        shape = [[0]*3 for _ in range(3)]
        for r, c in coords:
            sr = r - min_r
            sc = c - min_c
            if 0 <= sr < 3 and 0 <= sc < 3:
                shape[sr][sc] = color
        return shape

    shape_tl = extract_shape(c_tl)
    shape_tr = extract_shape(c_tr)
    shape_bl = extract_shape(c_bl)
    shape_br = extract_shape(c_br)

    # 4. Construct the 7x7 output grid
    output = [[0]*7 for _ in range(7)]

    # Place Top-Left quadrant (rows 0-2, cols 0-2)
    for r in range(3):
        for c in range(3):
            output[r][c] = shape_tl[r][c]

    # Place Top-Right quadrant (rows 0-2, cols 4-6)
    for r in range(3):
        for c in range(3):
            output[r][c + 4] = shape_tr[r][c]

    # Place Bottom-Left quadrant (rows 4-6, cols 0-2)
    for r in range(3):
        for c in range(3):
            output[r + 4][c] = shape_bl[r][c]

    # Place Bottom-Right quadrant (rows 4-6, cols 4-6)
    for r in range(3):
        for c in range(3):
            output[r + 4][c + 4] = shape_br[r][c]

    return output
